// Génère le PDF synthétique de test (10 pages, lettres US, Helvetica) :
// petit document déterministe (aucun binaire lourd dans le dépôt), utilisé
// par test/import.test.mjs (extraction + sections + OCR) et
// test/highlight.test.mjs (viewport réel pdf.js).
// Contenu (ASCII seulement, pour que l'extraction et l'OCR soient stables) :
//   p.1  couverture — « SYNTHETIC POH »
//   p.2  vide (comme la p. 2 du C150N)
//   p.3  « CONTENTS » — contient PERFORMANCE, sans sommaire détectable
//   p.4  SECTION 1 GENERAL — section 1 commence ici
//   p.5  SECTION 1 GENERAL — folio « ii »
//   p.6  SECTION 1 GENERAL
//   p.7  SECTION 1 GENERAL — folio « 1-1 »
//   p.8  SECTION 1 GENERAL — long paragraphe (> 500 caractères, pour l'OCR)
//   p.9  SECTION 2 LIMITATIONS — section 2 commence ici
//   p.10 SECTION 2 LIMITATIONS
// Sections attendues : front@1, 1@4, 2@9.
// Usage : node test/fixtures/synthetic-pdf.mjs  (écrit le PDF dans /tmp
// et affiche le chemin) — ou importer syntheticPdfPath() depuis un test.
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

export const SYNTHETIC_PAGES = [
  [
    'SYNTHETIC POH',
    'Test document for import tests',
    'Generated by test/fixtures/synthetic-pdf.mjs',
  ],
  [],
  [
    'CONTENTS',
    'This document covers GENERAL, LIMITATIONS and PERFORMANCE topics.',
  ],
  [
    'SECTION 1',
    'GENERAL',
    'General information about the airplane.',
    'The stall speed is 48 kt.',
  ],
  [
    'SECTION 1 GENERAL',
    'The airplane is a fictional single-engine airplane used for tests.',
    'ii',
  ],
  [
    'SECTION 1 GENERAL',
    'More general information.',
  ],
  [
    'SECTION 1 GENERAL',
    'Weight and balance data are in Section 6.',
    '1-1',
  ],
  [
    'SECTION 1',
    'GENERAL',
    'General information continued. The airplane is a',
    'fictional single-engine airplane built for tests.',
    'It has a fixed landing gear and a single piston',
    'engine. The airplane is used only for tests and',
    'training. It is not a real airplane and it never',
    'flies. The manual is fictional from cover to cover.',
    'All the pages exist to test the import of documents.',
    'The text is long enough to test the OCR of a page.',
    'Optical character recognition reads the printed',
    'words and turns them into searchable text. This',
    'paragraph is long so the test can check that more',
    'than five hundred characters are recognized here.',
    'The quick brown fox jumps over the lazy dog near',
    'the runway while the windsock points to the north.',
  ],
  [
    'SECTION 2',
    'LIMITATIONS',
    'The airplane must not be flown into known icing conditions.',
  ],
  [
    'SECTION 2 LIMITATIONS',
    'Limitations continued.',
  ],
];

function esc(s) {
  return s.replace(/\\/g, '\\\\').replace(/\(/g, '\\(').replace(/\)/g, '\\)');
}

function pageStream(lines) {
  let ops = 'BT /F1 14 Tf\n';
  let y = 750;
  for (const line of lines) {
    ops += `1 0 0 1 72 ${y} Tm (${esc(line)}) Tj\n`;
    y -= 28;
  }
  ops += 'ET';
  return ops;
}

export function syntheticPdfBuffer() {
  // Objets : 1 catalogue, 2 pages, 3 police, puis par page (contenu + page).
  const objects = [];
  objects[1] = '<< /Type /Catalog /Pages 2 0 R >>';
  objects[3] = '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>';
  const pageObjIds = [];
  const contentObjIds = [];
  let nextId = 4;
  for (let i = 0; i < SYNTHETIC_PAGES.length; i++) {
    pageObjIds.push(nextId);
    contentObjIds.push(nextId + 1);
    nextId += 2;
  }
  objects[2] = `<< /Type /Pages /Kids [${pageObjIds.map((id) => id + ' 0 R').join(' ')}] /Count ${SYNTHETIC_PAGES.length} >>`;
  for (let i = 0; i < SYNTHETIC_PAGES.length; i++) {
    const stream = pageStream(SYNTHETIC_PAGES[i]);
    objects[contentObjIds[i]] = `<< /Length ${Buffer.byteLength(stream)} >>\nstream\n${stream}\nendstream`;
    objects[pageObjIds[i]] =
      `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 3 0 R >> >> /Contents ${contentObjIds[i]} 0 R >>`;
  }

  let pdf = '%PDF-1.4\n';
  const offsets = [0];
  for (let id = 1; id < objects.length; id++) {
    offsets[id] = Buffer.byteLength(pdf);
    pdf += `${id} 0 obj\n${objects[id]}\nendobj\n`;
  }
  const xrefPos = Buffer.byteLength(pdf);
  const count = objects.length;
  pdf += `xref\n0 ${count}\n0000000000 65535 f \n`;
  for (let id = 1; id < count; id++) {
    pdf += String(offsets[id]).padStart(10, '0') + ' 00000 n \n';
  }
  pdf += `trailer\n<< /Size ${count} /Root 1 0 R >>\nstartxref\n${xrefPos}\n%%EOF\n`;
  return Buffer.from(pdf, 'utf8');
}

// Chemin du PDF généré (régénéré à chaque appel, dans /tmp — aucun
// binaire dans le dépôt).
export function syntheticPdfPath() {
  const outPath = path.join(os.tmpdir(), 'poh-synthetic-doc.pdf');
  fs.writeFileSync(outPath, syntheticPdfBuffer());
  return outPath;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const outPath = syntheticPdfPath();
  console.log('Écrit : ' + outPath + ' (' + fs.statSync(outPath).size + ' octets, 10 pages)');
}
